alter table asset_category add column if not exists category_code text,add column if not exists subsidiary_id bigint references subsidiaries,add column if not exists residual_value_percentage numeric(9,4)not null default 0 check(residual_value_percentage between 0 and 100),add column if not exists is_active boolean not null default true,add column if not exists description text;
alter table asset_category drop constraint if exists asset_category_category_name_key;
create unique index if not exists asset_category_subsidiary_name_idx on asset_category(subsidiary_id,lower(category_name))where subsidiary_id is not null;
create unique index if not exists asset_category_subsidiary_code_idx on asset_category(subsidiary_id,upper(category_code))where subsidiary_id is not null and category_code is not null;
update asset_category ac set subsidiary_id=coalesce((select min(a.subsidiary_id)from asset a where a.category_id=ac.category_id),(select min(subsidiary_id)from subsidiaries))where subsidiary_id is null;
alter table asset_category alter column subsidiary_id set not null;
drop policy if exists fixed_assets_select on asset_category;drop policy if exists fixed_assets_insert on asset_category;drop policy if exists fixed_assets_update on asset_category;drop policy if exists fixed_assets_delete on asset_category;create policy fixed_assets_select on asset_category for select to authenticated using(subsidiary_id=active_subsidiary_id());create policy fixed_assets_insert on asset_category for insert to authenticated with check(subsidiary_id=active_subsidiary_id());create policy fixed_assets_update on asset_category for update to authenticated using(subsidiary_id=active_subsidiary_id())with check(subsidiary_id=active_subsidiary_id());create policy fixed_assets_delete on asset_category for delete to authenticated using(subsidiary_id=active_subsidiary_id());

create or replace function asset_category_options()returns jsonb language sql stable security definer set search_path=public as $$select jsonb_build_object('subsidiary',jsonb_build_object('id',s.subsidiary_id,'name',s.name),'assetAccounts',coalesce((select jsonb_agg(jsonb_build_object('id',a.account_id,'number',a.account_number,'name',a.account_name)order by a.account_number)from chart_accounts a join account_subsidiaries x using(account_id)where x.subsidiary_id=s.subsidiary_id and x.is_active and a.accepts_entries and not a.is_inactive and(a.category='Activo'or a.account_type~*'activo')),'[]'),'depreciationAccounts',coalesce((select jsonb_agg(jsonb_build_object('id',a.account_id,'number',a.account_number,'name',a.account_name)order by a.account_number)from chart_accounts a join account_subsidiaries x using(account_id)where x.subsidiary_id=s.subsidiary_id and x.is_active and a.accepts_entries and not a.is_inactive and(a.account_name~*'depreciaci.n acumulada|amortizaci.n acumulada')),'[]'),'expenseAccounts',coalesce((select jsonb_agg(jsonb_build_object('id',a.account_id,'number',a.account_number,'name',a.account_name)order by a.account_number)from chart_accounts a join account_subsidiaries x using(account_id)where x.subsidiary_id=s.subsidiary_id and x.is_active and a.accepts_entries and not a.is_inactive and(a.category='Gasto'or a.account_type~*'gasto')),'[]'))from subsidiaries s where s.subsidiary_id=active_subsidiary_id()$$;
create or replace function asset_category_report(p_filters jsonb default'{}')returns jsonb language sql stable security definer set search_path=public as $$select jsonb_build_object('rows',coalesce(jsonb_agg(jsonb_build_object('id',c.category_id,'code',c.category_code,'name',c.category_name,'description',c.description,'usefulLife',c.useful_life_months,'method',c.depreciation_method,'residual',c.residual_value_percentage,'active',c.is_active,'assetAccountId',c.asset_account_id,'assetAccount',aa.account_number||' · '||aa.account_name,'depreciationAccountId',c.depreciation_account_id,'depreciationAccount',da.account_number||' · '||da.account_name,'expenseAccountId',c.depreciation_expense_account_id,'expenseAccount',ea.account_number||' · '||ea.account_name,'assets',coalesce(x.total,0))order by c.category_name),'[]'))from asset_category c join chart_accounts aa on aa.account_id=c.asset_account_id join chart_accounts da on da.account_id=c.depreciation_account_id join chart_accounts ea on ea.account_id=c.depreciation_expense_account_id left join lateral(select count(*)total from asset where category_id=c.category_id)x on true where c.subsidiary_id=active_subsidiary_id()and(coalesce(nullif(p_filters->>'search',''),'')=''or concat_ws(' ',c.category_code,c.category_name,c.description) ilike'%'||(p_filters->>'search')||'%')and(coalesce(p_filters->>'status','ALL')='ALL'or c.is_active=(p_filters->>'status'='ACTIVE'))$$;
create or replace function save_asset_category(p_payload jsonb,p_category_id bigint default null)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare sid bigint:=active_subsidiary_id();id bigint:=p_category_id;a bigint:=(p_payload->>'asset_account_id')::bigint;d bigint:=(p_payload->>'depreciation_account_id')::bigint;e bigint:=(p_payload->>'expense_account_id')::bigint;life int:=(p_payload->>'useful_life_months')::int;method text:=p_payload->>'method';begin if nullif(trim(p_payload->>'code'),'')is null or nullif(trim(p_payload->>'name'),'')is null then raise exception'Código y nombre son obligatorios.';end if;if method not in('Línea Recta','Suma de los Dígitos de los Años','No Depreciable')then raise exception'Método de depreciación inválido.';end if;if method<>'No Depreciable'and life<=0 then raise exception'La vida útil debe ser mayor que cero.';end if;if a=d or a=e or d=e then raise exception'Las tres cuentas contables deben ser diferentes.';end if;if exists(select 1 from unnest(array[a,d,e])account_id where not exists(select 1 from account_subsidiaries x join chart_accounts ca using(account_id)where x.account_id=account_id and x.subsidiary_id=sid and x.is_active and ca.accepts_entries and not ca.is_inactive))then raise exception'Una cuenta no está disponible para la subsidiaria.';end if;if id is null then insert into asset_category(category_code,category_name,description,subsidiary_id,useful_life_months,depreciation_method,residual_value_percentage,asset_account_id,depreciation_account_id,depreciation_expense_account_id,is_active)values(upper(trim(p_payload->>'code')),trim(p_payload->>'name'),p_payload->>'description',sid,case when method='No Depreciable'then 1 else life end,method,coalesce(nullif(p_payload->>'residual','')::numeric,0),a,d,e,coalesce((p_payload->>'active')::boolean,true))returning category_id into id;else update asset_category set category_code=upper(trim(p_payload->>'code')),category_name=trim(p_payload->>'name'),description=p_payload->>'description',useful_life_months=case when method='No Depreciable'then 1 else life end,depreciation_method=method,residual_value_percentage=coalesce(nullif(p_payload->>'residual','')::numeric,0),asset_account_id=a,depreciation_account_id=d,depreciation_expense_account_id=e,is_active=coalesce((p_payload->>'active')::boolean,true)where category_id=id and subsidiary_id=sid;if not found then raise exception'Categoría no encontrada.';end if;end if;return jsonb_build_object('id',id,'message','Categoría guardada correctamente.');end$$;
create or replace function delete_asset_category(p_category_id bigint)returns boolean language plpgsql security definer set search_path=public as $$begin if exists(select 1 from asset a join asset_category c using(category_id)where a.category_id=p_category_id and c.subsidiary_id=active_subsidiary_id())then raise exception'No se puede eliminar porque existen activos asociados. Puede marcarla como inactiva.';end if;delete from asset_category where category_id=p_category_id and subsidiary_id=active_subsidiary_id();if not found then raise exception'Categoría no encontrada.';end if;return true;end$$;
revoke all on function asset_category_options(),asset_category_report(jsonb),save_asset_category(jsonb,bigint),delete_asset_category(bigint)from public,anon;grant execute on function asset_category_options(),asset_category_report(jsonb),save_asset_category(jsonb,bigint),delete_asset_category(bigint)to authenticated;notify pgrst,'reload schema';
